#include "ClassicPluginActions.qak.h"

namespace hello::daw {

    namespace {

        std::filesystem::path pluginsOf(const std::filesystem::path &utauDirectory) {
            return utauDirectory.empty() ? std::filesystem::path() : utauDirectory / u"plugins";
        }

        // Opens \a directory in the file manager, and creates it if necessary.
        void open(const std::filesystem::path &directory) {
            std::error_code error;
            std::filesystem::create_directories(directory, error);
            QDesktopServices::openUrl(
                QUrl::fromLocalFile(QString::fromStdU16String(directory.u16string())));
        }

    }

    ClassicPluginContribution::ClassicPluginContribution() = default;

    ClassicPluginContribution::~ClassicPluginContribution() = default;

    const QAK::ActionExtension *ClassicPluginContribution::extension() const {
        return classicPluginActions();
    }

    void ClassicPluginContribution::addActions(ProjectWindow *window,
                                               QAK::WidgetActionContext *context) {
        // An external action. This plugin fills its menu each time the menu opens.
        const auto menu = new QMenu(window);
        menu->setToolTipsVisible(true);
        QObject::connect(menu, &QMenu::aboutToShow, menu,
                         [this, menu, window] { fill(menu, window); });
        // Converted from UTF-8 rather than a literal, whose data would be unloaded with this
        // library
        context->addAction(QString::fromUtf8("helloutau.tools.classicPlugins"), menu->menuAction());

        // The menu at the mouse pointer. The action is in no menu, so the window holds it for its
        // shortcut to take effect.
        const auto atPointer = new QAction(window);
        window->addAction(atPointer);
        const QPointer<QMenu> guarded(menu);
        QObject::connect(atPointer, &QAction::triggered, window, [guarded] {
            if (guarded) {
                guarded->popup(QCursor::pos());
            }
        });
        context->addAction(QString::fromUtf8("helloutau.tools.classicPluginsAtPointer"), atPointer);
    }

    std::filesystem::path ClassicPluginContribution::userDirectory() {
        return std::filesystem::path(
                   QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)
                       .toStdU16String()) /
               u"UtauPlugins";
    }

    void ClassicPluginContribution::fill(QMenu *menu, ProjectWindow *window) {
        if (m_utauDirectory != window->editor()->settings().utauDirectory()) {
            refresh(window);
        }

        menu->clear();
        for (const auto &plugin : std::as_const(m_plugins)) {
            // The name is plain text. An ampersand in it is not a mnemonic.
            auto name = plugin.name;
            const auto action =
                menu->addAction(name.replace(QLatin1Char('&'), QLatin1String("&&")));
            action->setEnabled(plugin.isAvailable());
            action->setToolTip(plugin.unavailableReason);
            QObject::connect(action, &QAction::triggered, window,
                             [window, plugin] { runClassicPlugin(window, plugin); });
        }
        if (m_plugins.isEmpty()) {
            menu->addAction(tr("No Plugins"))->setEnabled(false);
        }

        menu->addSeparator();
        QObject::connect(menu->addAction(tr("&Refresh")), &QAction::triggered, window,
                         [this, window] { refresh(window); });
        QObject::connect(menu->addAction(tr("&Open Plugin Folder")), &QAction::triggered, window,
                         [] { open(userDirectory()); });
        const auto utauPlugins = pluginsOf(window->editor()->settings().utauDirectory());
        if (!utauPlugins.empty()) {
            QObject::connect(menu->addAction(tr("Open &UTAU Plugin Folder")), &QAction::triggered,
                             window, [utauPlugins] { open(utauPlugins); });
        }
    }

    void ClassicPluginContribution::refresh(ProjectWindow *window) {
        const auto utauDirectory = window->editor()->settings().utauDirectory();
        QList<std::filesystem::path> directories;
        if (const auto utauPlugins = pluginsOf(utauDirectory); !utauPlugins.empty()) {
            directories.push_back(utauPlugins);
        }
        directories.push_back(userDirectory());

        // A folder whose plugin.txt cannot be read is skipped, as in UTAU.
        kit::DiagnosticList diagnostics;
        m_plugins = ClassicPlugin::discover(directories, diagnostics);
        m_utauDirectory = utauDirectory;
    }

}
